/* libsomrando: C port of Moppu/SecretOfManaRandomizer v1.49 (commit 1404b7b).  LGPL-2.1 or later, see sr_core.h and COPYING.LIB.
 *
 * Open World prizes (event data of every prize).  Derived from processing/openworld/randomization/OpenWorldPrizes.cs (Author: Moppleton).
 * Translated to C 2026-10-18.  The per-prize event data (weapons, seeds, spells, items, characters) is generated by tools/gen_p4_core.py
 * (sr_p4_ow_core_prz_body.inc); the hand written parts are the setup before it and the gold / weapon orb / nothing padding after it.
 * The plando setting is only supported empty: startingItems stays empty and the "(NON-EXISTENT)" padding is zero. */
#include <stdio.h>
#include <string.h>

#include "sr_p4.h"
#include "sr_p4_ow.h"
#include "sr_p4_ow_core_int.h"

#include "sr_p4_ow_core_lists.inc"

#define PZ_ADD(name, type, bytes, hint, flag, value) sr_p4_core_prize_add(c, &allPrizes, (name), (type), (bytes), (hint), (flag), (value))

static const char *const prize_prefixes[] = {
  "%1!", "%1.", "%1!", "You got %1!", "You got %1.", "You got %1!", "Got %1!", "Got %1.", "Got %1!", "It's %1!", "It's %1.", "Found %1.",
  "Found %1!", "Found %1.", "Received %1.", "Received %1!", "Received %1.", "Nice, it's %1!", "Finally, it's %1!",
  "Just what you always wanted: %1.", "Oh hey, it's %1.", "Just for you: %1.", "Well, if it isn't %1!",
};
#define N_PREFIXES ((int)(sizeof prize_prefixes / sizeof *prize_prefixes))

void sr_p4_core_gold_flags_init(uint8_t *flags, int *n) {
  memcpy(flags, ow_gold_flags, OW_GOLD_FLAGS_N);
  *n = OW_GOLD_FLAGS_N;
}

/* VanillaEventUtil.wordWrapText */
static char *word_wrap(struct sr_ctx *c, const char *text) {
  size_t len = strlen(text);
  if (strchr(text, '\n')) {
    char *same = (char *)sr_alloc(c, len + 1);
    memcpy(same, text, len);
    return same;
  }
  /* every token adds at most its length + 2 */
  char *out = (char *)sr_alloc(c, len * 2 + 8);
  size_t o = 0, width = 0;
  const char *p = text;
  for (;;) {
    const char *sp = strchr(p, ' ');
    size_t tl = sp ? (size_t)(sp - p) : strlen(p);
    if (tl + width < 27) {
      memcpy(out + o, p, tl);
      o += tl;
      out[o++] = ' ';
      width += tl + 1;
    } else {
      out[o++] = '\n';
      memcpy(out + o, p, tl);
      o += tl;
      out[o++] = ' ';
      width = tl + 1;
    }
    if (!sp) break;
    p = sp + 1;
  }
  out[o] = 0;
  return out;
}

void sr_p4_core_gift_text_fmt(struct sr_ctx *c, struct sr_bytes *out, const char *const *formats, int n_formats, const char *prize_name) {
  const char *format = formats[sr_random_next(&c->rf) % n_formats];
  size_t pl = strlen(prize_name), fl = strlen(format);
  char *f = (char *)sr_alloc(c, fl + pl + 2);
  size_t o = 0;
  const char *p = format;
  /* String.Replace("%1", prizeName) */
  while (*p) {
    if (p[0] == '%' && p[1] == '1') {
      memcpy(f + o, prize_name, pl);
      o += pl;
      p += 2;
    } else {
      f[o++] = *p++;
    }
  }
  f[o] = 0;
  if (f[0] >= 'a' && f[0] <= 'z') f[0] = (char)(f[0] - 'a' + 'A');
  sr_event_text_bytes(c, out, word_wrap(c, f));
}

void sr_p4_core_gift_text(struct sr_ctx *c, struct sr_bytes *out, const char *prize_name) {
  sr_p4_core_gift_text_fmt(c, out, prize_prefixes, N_PREFIXES, prize_name);
}

/* OpenWorldPrizes.getForSelectedOptions; the filtered location list is the full list because the Christmas goals are refused */
void sr_p4_core_prizes(struct sr_ctx *c, struct ow_prizes *P, const struct ow_locs *allLocations) {
  struct ow_prizes allPrizes = {0};
  int boyExists = sr_p4_core_w_bool(c, "boyExists");
  int girlExists = sr_p4_core_w_bool(c, "girlExists");
  int spriteExists = sr_p4_core_w_bool(c, "spriteExists");
  int startWithBoy = sr_p4_core_w_bool(c, "startWithBoy");
  int startWithGirl = sr_p4_core_w_bool(c, "startWithGirl");
  int startWithSprite = sr_p4_core_w_bool(c, "startWithSprite");
  int findBoy = sr_p4_core_w_bool(c, "findBoy");
  int findGirl = sr_p4_core_w_bool(c, "findGirl");
  int findSprite = sr_p4_core_w_bool(c, "findSprite");
  const char *startingChar = sr_p4_core_w_str(c, "startingCharacter");
  const char *boyClass = sr_p4_core_w_str(c, "boyClass");
  const char *girlClass = sr_p4_core_w_str(c, "girlClass");
  const char *spriteClass = sr_p4_core_w_str(c, "spriteClass");
  const char *goal = sr_p4_core_w_str(c, "openWorldGoalShortName");
  int girlSpellsExist = sr_p4_core_w_bool(c, "girlMagicExists");
  int spriteSpellsExist = sr_p4_core_w_bool(c, "spriteMagicExists");
  int flammieDrumInLogic = sr_settings_get_bool(c->settings, "opFlammieDrumInLogic");
  int anyCharsAdded = !sr_p4_core_w_bool(c, "startSolo");
  int skipWeaponOrbs = sr_settings_get_bool(c->settings, "opAllWeaponOrbs");
  struct sr_random *r = &c->rf;
  struct ow_slist startingItems = {0};

  int boyStarterWeapon = sr_p4_core_w_int(c, "boyStartWeapon");
  int girlStarterWeapon = sr_p4_core_w_int(c, "girlStartWeapon");
  int spriteStarterWeapon = sr_p4_core_w_int(c, "spriteStartWeapon");
  struct ow_ilist weaponIndexes = {0};
  for (int i = 0; i < 8; i++) sr_p4_core_il_add(c, &weaponIndexes, i);
  sr_p4_core_il_remove(&weaponIndexes, boyStarterWeapon);
  sr_p4_core_il_remove(&weaponIndexes, girlStarterWeapon);
  sr_p4_core_il_remove(&weaponIndexes, spriteStarterWeapon);

  struct sr_bytes altStarterWeaponFlags = {0};
  int starterWeaponId = -1;
  if (startWithBoy && strcmp(startingChar, "boy")) {
    sr_bytes_push(c, &altStarterWeaponFlags, 0xC0 + boyStarterWeapon);
    sr_bytes_push(c, &altStarterWeaponFlags, 0xC8 + boyStarterWeapon);
  }
  if (startWithGirl && strcmp(startingChar, "girl")) {
    sr_bytes_push(c, &altStarterWeaponFlags, 0xC0 + girlStarterWeapon);
    sr_bytes_push(c, &altStarterWeaponFlags, 0xC8 + girlStarterWeapon);
  }
  if (startWithSprite && strcmp(startingChar, "sprite")) {
    sr_bytes_push(c, &altStarterWeaponFlags, 0xC0 + spriteStarterWeapon);
    sr_bytes_push(c, &altStarterWeaponFlags, 0xC8 + spriteStarterWeapon);
  }
  int starterWeaponFlag = 0;
  if (!strcmp(startingChar, "boy")) {
    starterWeaponFlag = (uint8_t)(0xC0 + boyStarterWeapon);
    starterWeaponId = boyStarterWeapon;
  }
  if (!strcmp(startingChar, "girl")) {
    starterWeaponFlag = (uint8_t)(0xC0 + girlStarterWeapon);
    starterWeaponId = girlStarterWeapon;
  }
  if (!strcmp(startingChar, "sprite")) {
    starterWeaponFlag = (uint8_t)(0xC0 + spriteStarterWeapon);
    starterWeaponId = spriteStarterWeapon;
  }

  struct sr_bytes startingRewardsEventData = {0};
  sr_bytes_push(c, &startingRewardsEventData, 0x29);
  sr_bytes_push(c, &startingRewardsEventData, starterWeaponFlag);
  sr_bytes_push(c, &startingRewardsEventData, 0x29);
  sr_bytes_push(c, &startingRewardsEventData, starterWeaponFlag + 8);
  sr_bytes_push(c, &startingRewardsEventData, 0x1F);
  sr_bytes_push(c, &startingRewardsEventData, 0x08);
  sr_bytes_push(c, &startingRewardsEventData, 0x2F);
  sr_bytes_push(c, &startingRewardsEventData, 0x44);
  sr_p4_core_gift_text(c, &startingRewardsEventData, sr_p4_core_cat(c, "the ", sr_p4_core_weapon_name(starterWeaponId), NULL));

  struct sr_bytes girlSpriteStarterWeaponEventData = {0};
  for (size_t i = 0; i < altStarterWeaponFlags.len; i++) {
    sr_bytes_push(c, &girlSpriteStarterWeaponEventData, 0x29);
    sr_bytes_push(c, &girlSpriteStarterWeaponEventData, altStarterWeaponFlags.p[i]);
  }
  sr_bytes_push(c, &girlSpriteStarterWeaponEventData, 0x1F);
  sr_bytes_push(c, &girlSpriteStarterWeaponEventData, 0x08);
  sr_bytes_push(c, &girlSpriteStarterWeaponEventData, 0x2F);
  sr_bytes_push(c, &girlSpriteStarterWeaponEventData, 0x44);

#include "sr_p4_ow_core_prz_body.inc"

  /* list of locations that the filtered list would contain (unfiltered for the supported goals) */
  int numGoldEvents = 0;
  int maxPrizes = sr_p4_core_filtered_count(c, allLocations);
  if (strcmp(goal, "xmas2020")) {
    if (!girlSpellsExist) gold_flags[n_gold_flags++] = 0xAC;
    if (!spriteSpellsExist) gold_flags[n_gold_flags++] = 0xAD;
    if (!girlSpellsExist && !spriteSpellsExist) {
      gold_flags[n_gold_flags++] = 0xA9;
      gold_flags[n_gold_flags++] = 0xA8;
      gold_flags[n_gold_flags++] = 0xAB;
      gold_flags[n_gold_flags++] = 0xAA;
      gold_flags[n_gold_flags++] = 0xAE;
      gold_flags[n_gold_flags++] = 0xAF;
    }
  }
  int maxGoldEvents = n_gold_flags;
  double goldMultiplier = sr_settings_get_double(c->settings, "opGoldCheckMul");
  while (numGoldEvents < maxGoldEvents && allPrizes.n < maxPrizes) {
    struct sr_bytes give1000GoldEventData = {0};
    sr_bytes_push(c, &give1000GoldEventData, 0x42);
    sr_bytes_push(c, &give1000GoldEventData, gold_flags[numGoldEvents]);
    sr_bytes_push(c, &give1000GoldEventData, 0x1F);
    sr_bytes_push(c, &give1000GoldEventData, 0x10 + 0x03);
    sr_bytes_push(c, &give1000GoldEventData, 0x96);
    int goldAmount = (int)(100 * goldMultiplier + (sr_random_next(r) % 10) * 100 * goldMultiplier);
    if (goldAmount > 65535) goldAmount = 65535;
    sr_bytes_push(c, &give1000GoldEventData, 0x36);
    sr_bytes_push(c, &give1000GoldEventData, goldAmount);
    sr_bytes_push(c, &give1000GoldEventData, goldAmount >> 8);
    char amount[16];
    snprintf(amount, sizeof amount, "%d", goldAmount);
    sr_p4_core_gift_text(c, &give1000GoldEventData, sr_p4_core_cat(c, amount, " gold", NULL));
    sr_bytes_push(c, &give1000GoldEventData, 0x29);
    sr_bytes_push(c, &give1000GoldEventData, gold_flags[numGoldEvents]);
    char idx[16];
    snprintf(idx, sizeof idx, "%d", numGoldEvents);
    PZ_ADD(sr_p4_core_cat(c, "GP ", idx, ": ", amount, NULL), "", &give1000GoldEventData, "some gold", gold_flags[numGoldEvents], 0.4);
    numGoldEvents++;
  }

  int orbEventNum = 0x500;
  PZ_ADD("starter weapon (main)", "weapon", &startingRewardsEventData, "", 0x00, 1.0);

  int orbNum = 0;
  while (allPrizes.n < maxPrizes && orbNum < OW_ORB_FLAGS_N) {
    int weaponId = orbEventNum - 0x500;
    struct sr_bytes orbEventData = {0};
    sr_bytes_push(c, &orbEventData, 0x42);
    sr_bytes_push(c, &orbEventData, ow_orb_flags[orbNum]);
    sr_bytes_push(c, &orbEventData, 0x1F);
    sr_bytes_push(c, &orbEventData, 0x10 + 0x03);
    sr_bytes_push(c, &orbEventData, 0x96);
    sr_bytes_push(c, &orbEventData, 0x29);
    sr_bytes_push(c, &orbEventData, ow_orb_flags[orbNum]);

    if (skipWeaponOrbs) {
      int goldAmount = (int)(100 * goldMultiplier + (sr_random_next(r) % 10) * 100 * goldMultiplier);
      if (goldAmount > 65535) goldAmount = 65535;
      sr_bytes_push(c, &orbEventData, 0x36);
      sr_bytes_push(c, &orbEventData, goldAmount);
      sr_bytes_push(c, &orbEventData, goldAmount >> 8);
      char amount[16], idx[16];
      snprintf(amount, sizeof amount, "%d", goldAmount);
      snprintf(idx, sizeof idx, "%d", numGoldEvents);
      sr_p4_core_gift_text(c, &orbEventData, sr_p4_core_cat(c, amount, " gold", NULL));
      PZ_ADD(sr_p4_core_cat(c, "GP ", idx, ": ", amount, NULL), "", &orbEventData, "some gold", ow_orb_flags[orbNum], 0.4);
      numGoldEvents++;
      orbNum++;
    } else {
      sr_bytes_push(c, &orbEventData, 0x42);
      sr_bytes_push(c, &orbEventData, 0xB8 + weaponId);
      sr_bytes_push(c, &orbEventData, 0x08);
      sr_bytes_push(c, &orbEventData, 0x29);
      sr_bytes_push(c, &orbEventData, 0xB8 + weaponId);

      sr_bytes_push(c, &orbEventData, 0x42);
      sr_bytes_push(c, &orbEventData, 0xC0 + weaponId);
      sr_bytes_push(c, &orbEventData, 0x08);
      sr_bytes_push(c, &orbEventData, 0x29);
      sr_bytes_push(c, &orbEventData, 0xC0 + weaponId);

      const char *prefix = weaponId == 2 ? "an" : "a";
      sr_p4_core_gift_text(c, &orbEventData, sr_p4_core_cat(c, prefix, " ", sr_p4_core_weapon_name(weaponId), "'s Orb", NULL));

      orbEventNum++;
      if (orbEventNum == 0x508) orbEventNum = 0x500;

      PZ_ADD(sr_p4_core_cat(c, sr_p4_core_weapon_name(weaponId), " orb", NULL), "", &orbEventData, "a weapon orb", ow_orb_flags[orbNum], 0.5);
      orbNum++;
    }
  }

  /* pad the prize list with nothings (no plando: no "(NON-EXISTENT)" entries) */
  static const char *const nothingPhrases[] = {"Nothing!", "Sorry nothing", "Oops no item", "Someone else got your item", "Nothing at all!"};
  while (allPrizes.n < maxPrizes) {
    struct sr_bytes nothingEventData = {0};
    if (sr_random_next(r) % 2 == 0) {
      sr_p4_core_gift_text(c, &nothingEventData, "Nothing");
    } else {
      const char *phrase = nothingPhrases[sr_random_next(r) % 5];
      sr_event_text_bytes(c, &nothingEventData, phrase);
    }
    PZ_ADD("nothing", "", &nothingEventData, "nothing", 0x00, 0.1);
  }
  *P = allPrizes;

  (void)boyExists; (void)girlExists; (void)spriteExists; (void)findBoy; (void)findGirl; (void)findSprite; (void)boyClass; (void)girlClass;
  (void)spriteClass; (void)flammieDrumInLogic; (void)anyCharsAdded; (void)startingItems; (void)weaponIndexes; (void)ow_flammie_required;
  (void)ow_upperland_required;
}
